    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
    Content = new StringContent("{\"compliance_status\":\"compliant\",\"compliance_notes\":\"string\",\"insurance_status\":\"compliant\",\"insurance_notes\":\"string\"}")
